<template><picker :range="options" range-key="label" :value="index" @change="$emit('update:modelValue',options[$event.detail.value].value)"><view class="select-field"><text>{{options[index]?.label||placeholder}}</text><FIcon name="down" :size="14"/></view></picker></template>
<script setup>import {computed} from 'vue';import FIcon from './FIcon.vue';const props=defineProps({options:{default:()=>[]},modelValue:{},placeholder:{default:'请选择'}});defineEmits(['update:modelValue']);const index=computed(()=>Math.max(0,props.options.findIndex(x=>String(x.value)===String(props.modelValue))))</script>
